                    NAME( <USRHLQ>.<CMASAPPL>.EYUDREP ) -
                    STORCLAS( STANDARD )           -
                    RECORDS( 500 3000  )           -
                    CONTROLINTERVALSIZE( 8192 )    -
                    RECSZ(200,6550)                -
                    KEYS(64,0)                     -
                    SHR(2)                         -
                    SPEED                          -
                    REUSE                          -
                    ERASE                          -
                    INDEXED                        -
